import React from "react";
import { AbsoluteFill, Easing, Img, interpolate, staticFile, useCurrentFrame } from "remotion";
import {
  BLACK, CREAM, EMBER, EMBER_HI, Flash, INOUT, LEAD, Lettering, Logo, OUT, Photo, SANS, Shade, WIDE, Wrap, cl, k, lin, pop,
} from "./Marcio";
import type { Tr } from "./Marcio";

// RUIZ BRASA BURGER · v2. Retorno no v1: "preciso de mais motion". Mesma voz (o locutor, voz-v1.mp3) e mesmos tempos;
// agora alterna cena desenhada e foto: abre numa grelha desenhada (brasa, chama, carne caindo, fumaça), as fotos ganham
// ícones desenhados por item, o burger é montado camada por camada e leva uma mordida, os dias viram folhas de calendário
// com relógio e lua. Faíscas de brasa só na marca e no fecho (são a identidade, não enfeite).

export const MR2_FPS = 30;
export const MR2_FRAMES = Math.round(25.3 * MR2_FPS);

const T_C = 3.12, T_D = 4.55, T_E = 6.0, T_F = 9.45, T_F2 = 10.5, T_F3 = 11.6, T_G = 13.3, T_H = 16.6, T_I = 19.7;

const BUN = "#DE9F55", BUN_HI = "#F2C27E", BUN_LO = "#B9752F", MEAT = "#4A2416", MEAT_HI = "#6B3620", CHEESE = "#F4A936";
const LETTUCE = "#78B843", TOMATO = "#D9432F", BACON = "#B4452C", GRATE = "#9A8E86";

// ruído determinístico
const rnd = (i: number) => { const x = Math.sin(i * 127.1 + 311.7) * 43758.5453; return x - Math.floor(x); };

// chama desenhada (base em 0,0; altura 100)
const FlamePath = "M0 0 C-38 0 -46 -30 -34 -52 C-26 -66 -18 -70 -16 -92 C-4 -78 2 -66 0 -52 C8 -60 12 -70 10 -84 C30 -66 44 -40 36 -20 C30 -6 18 0 0 0 Z";
const Flame: React.FC<{ x: number; y: number; h: number; t: number; seed: number; color?: string; inner?: boolean; flare?: number }> = ({ x, y, h, t, seed, color = EMBER, inner = true, flare = 1 }) => {
  const f = 1 + 0.12 * Math.sin(t * 13 + seed * 2.1) + 0.07 * Math.sin(t * 23 + seed);
  const sk = 5 * Math.sin(t * 7 + seed * 1.3);
  const s = (h / 100) * flare;
  return (
    <g transform={`translate(${x} ${y}) skewX(${sk.toFixed(2)}) scale(${(s * (2 - f) * 0.5 + s * 0.5).toFixed(3)} ${(s * f).toFixed(3)})`}>
      <path d={FlamePath} fill={color} />
      {inner ? <path d={FlamePath} fill={EMBER_HI} transform="scale(0.55)" /> : null}
      {inner ? <path d={FlamePath} fill="#FFD27A" transform="scale(0.25)" /> : null}
    </g>
  );
};

// faíscas subindo
const Sparks: React.FC<{ t: number; from: number; n?: number; y0?: number }> = ({ t, from, n = 14, y0 = 1920 }) => (
  <svg width={1080} height={1920} style={{ position: "absolute", left: 0, top: 0 }}>
    {[...Array(n)].map((_, i) => {
      const life = 1.6 + rnd(i) * 1.4;
      const born = from + rnd(i + 50) * 2.5;
      const age = ((t - born) % life + life) % life;
      if (t < born) return null;
      const p = age / life;
      const x = 140 + rnd(i + 9) * 800 + Math.sin(age * 3 + i) * 30;
      const y = y0 - p * (700 + rnd(i + 3) * 500);
      return <circle key={i} cx={x} cy={y} r={3 + rnd(i + 7) * 5} fill={EMBER_HI} opacity={(1 - p) * (0.6 + 0.4 * Math.sin(t * 20 + i))} />;
    })}
  </svg>
);

// ───────── 1 · grelha desenhada: a carne cai na brasa, a chama sobe no "churrasco" ─────────
const Grelha: React.FC<{ t: number }> = ({ t }) => {
  const drop = interpolate(t, [-0.15, 0.2], [0, 1], { ...cl, easing: Easing.in(Easing.quad) });
  const land = t > 0.2 ? Math.max(0, 1 - (t - 0.2) / 0.35) * Math.sin(((t - 0.2) / 0.35) * Math.PI * 2) : 0;
  const flare = 1 + 0.55 * interpolate(t, [0.95, 1.15, 2.0], [0, 1, 0.25], cl);
  const cam = interpolate(t, [-0.15, 1.7], [1.55, 1.3], { ...cl, easing: OUT });
  const punch = interpolate(t, [1.7, 1.9], [0, 1], { ...cl, easing: OUT });
  const sear = lin(t, 0.4, 2.6);
  return (
    <AbsoluteFill style={{ background: BLACK }}>
      <AbsoluteFill style={{ transform: `scale(${(cam + 0.1 * punch + 0.03 * lin(t, 1.9, T_C)).toFixed(4)}) rotate(${(-2 * punch + 2 * lin(t, 1.9, T_C) * punch).toFixed(2)}deg)`, transformOrigin: "540px 1250px" }}>
        {/* brilho da brasa no fundo */}
        <div style={{ position: "absolute", left: 40, right: 40, top: 1180, height: 640, borderRadius: "50%", background: "radial-gradient(closest-side, rgba(240,110,40,0.38), rgba(240,110,40,0))", opacity: 0.8 + 0.2 * Math.sin(t * 5) }} />
        <svg width={1080} height={1920} style={{ position: "absolute", left: 0, top: 0 }}>
          {/* fumaça subindo da carne */}
          {[0, 1, 2, 3].map((i) => {
            const st = 0.35 + i * 0.3;
            if (t < st) return null;
            const a = (t - st) % 1.8;
            const p = a / 1.8;
            const x = 400 + i * 95;
            const y = 1080 - p * 300;
            return <path key={i} d={`M${x} ${y + 160} C${x - 40} ${y + 110} ${x + 40} ${y + 60} ${x} ${y}`} stroke={CREAM} strokeWidth={14 - 6 * p} strokeLinecap="round" fill="none" opacity={(1 - p) * 0.35 * sear} />;
          })}
          {/* chamas atrás da grelha */}
          {[0, 1, 2, 3, 4, 5, 6].map((i) => (
            <Flame key={i} x={200 + i * 113} y={1430} h={(140 + 70 * rnd(i)) * k(t, -0.1 + i * 0.04, 0.4)} t={t} seed={i} flare={flare} color={i % 2 ? EMBER : "#C24A22"} />
          ))}
          {/* brasas */}
          {[...Array(13)].map((_, i) => {
            const glow = 0.5 + 0.5 * Math.sin(t * (3 + rnd(i) * 3) + i);
            return <ellipse key={i} cx={170 + i * 62} cy={1440 + (i % 2) * 26} rx={52} ry={34} fill={`rgb(${(110 + 130 * glow).toFixed(0)},${(30 + 60 * glow).toFixed(0)},20)`} />;
          })}
          <rect x={120} y={1460} width={840} height={110} rx={20} fill="#1B1412" />
          <rect x={120} y={1460} width={840} height={14} fill="#2A201C" />
          {/* grelha */}
          <rect x={110} y={1250} width={860} height={20} rx={10} fill={GRATE} />
          {[...Array(9)].map((_, i) => <rect key={i} x={140 + i * 100} y={1262} width={8} height={30} fill="#6E655F" />)}
          {/* hambúrguer de carne caindo na grelha */}
          <g transform={`translate(540 ${(1250 - (1 - drop) * 1300).toFixed(1)}) scale(${(1 + 0.12 * land).toFixed(3)} ${(1 - 0.14 * land).toFixed(3)})`}>
            <rect x={-240} y={-150} width={480} height={150} rx={64} fill={MEAT} />
            <rect x={-215} y={-142} width={430} height={40} rx={20} fill={MEAT_HI} />
            {/* crosta escurecendo */}
            <rect x={-240} y={-50} width={480} height={50} rx={25} fill="#2A120A" opacity={0.3 + 0.6 * sear} />
            {[...Array(7)].map((_, i) => <circle key={i} cx={-170 + i * 57} cy={-85 + (i % 2) * 18} r={7} fill="#2A120A" opacity={0.6} />)}
          </g>
          {/* gotas de gordura caindo no fogo */}
          {[0, 1, 2].map((i) => {
            const st = 0.9 + i * 0.6; const a = t - st;
            if (a < 0 || a > 0.35) return null;
            return <ellipse key={i} cx={420 + i * 120} cy={1275 + a * 500} rx={7} ry={11} fill={CHEESE} opacity={1 - a / 0.35} />;
          })}
        </svg>
      </AbsoluteFill>
      <Lettering t={t} items={[["Sabe aquele sabor", 0.13], ["de churrasco?", 0.89, true]]} bottom={1200} base={120} out={T_C - 0.12} />
    </AbsoluteFill>
  );
};

// ───────── 2 · a foto do burger cai no quadro ─────────
const Agora: React.FC<{ t: number }> = ({ t }) => {
  const e = interpolate(t, [T_C - 0.12, T_C + 0.25], [0, 1], { ...cl, easing: Easing.out(Easing.back(1.4)) });
  return (
    <AbsoluteFill>
      <AbsoluteFill style={{ transform: `translateY(${((1 - e) * -2100).toFixed(1)}px) rotate(${((1 - e) * -6).toFixed(2)}deg)` }}>
        <Photo t={t} src="b0604" a={T_C - 0.2} b={T_D + 0.2} cam={{ z: [1.2, 1.04], y: [-150, 60] }} />
        <Shade />
        <Lettering t={t} items={[["Agora ele tá", 3.17], ["no hambúrguer", 3.65, true]]} />
      </AbsoluteFill>
    </AbsoluteFill>
  );
};

// ───────── 3 · a marca: chamas desenhadas sobem, a chama do logo acende ─────────
const Marca: React.FC<{ t: number }> = ({ t }) => {
  const up = k(t, T_D - 0.1, 0.5);
  return (
    <AbsoluteFill style={{ background: BLACK }}>
      <div style={{ position: "absolute", left: 0, right: 0, bottom: -60, height: 700, background: "radial-gradient(60% 70% at 50% 100%, rgba(210,88,42,0.55), rgba(210,88,42,0))", opacity: up }} />
      <svg width={1080} height={1920} style={{ position: "absolute", left: 0, top: 0 }}>
        {[...Array(9)].map((_, i) => (
          <Flame key={i} x={60 + i * 120} y={1990} h={(220 + 160 * rnd(i + 20)) * up} t={t} seed={i + 4} color={i % 2 ? "#B8441D" : EMBER} />
        ))}
      </svg>
      <Sparks t={t} from={T_D} n={16} y0={1750} />
      <div style={{ position: "absolute", left: 540 - 430, top: 560, transform: `scale(${(0.9 + 0.22 * lin(t, T_D, T_E + 0.3)).toFixed(4)}) rotate(${(-3 + 3 * lin(t, T_D, T_E)).toFixed(2)}deg)`, transformOrigin: "430px 290px" }}>
        <Logo t={t} flame={4.6} word={5.0} w={860} />
      </div>
    </AbsoluteFill>
  );
};

// ───────── 4 · foto na mão, logo pequeno e selo de chama no "de verdade" ─────────
const Brasa: React.FC<{ t: number }> = ({ t }) => {
  const lg = k(t, T_E + 0.15, 0.5);
  return (
    <AbsoluteFill>
      <Photo t={t} src="b1958" a={T_E - 0.3} b={T_F + 0.3} cam={{ z: [1.32, 1.02], x: [70, -40], r: [2.5, -0.5], o: "55% 55%" }} pos="55% 50%" />
      <div style={{ position: "absolute", left: 0, right: 0, top: 0, height: 520, background: "linear-gradient(180deg, rgba(10,8,7,0.7) 0%, rgba(10,8,7,0) 100%)" }} />
      <div style={{ position: "absolute", left: 540 - 190, top: 110, opacity: lg, transform: `translateY(${((1 - lg) * -30).toFixed(1)}px)` }}>
        <Img src={staticFile("marcio/logo-t.png")} style={{ width: 380, height: 380 * 625 / 940 }} />
      </div>
      <Shade h={1000} />
      <Lettering t={t} items={[["Hamburgueria", 6.04], ["na brasa", 7.42], ["de verdade", 8.4, true]]} />
    </AbsoluteFill>
  );
};

// ───────── 5 · cada item: foto + ícone desenhado num selo ─────────
const IcoFlame: React.FC<{ t: number }> = ({ t }) => (
  <svg width={130} height={130} viewBox="-60 -110 120 120"><Flame x={0} y={0} h={105} t={t} seed={3} color={CREAM} inner={false} /></svg>
);
const IcoDrip: React.FC<{ t: number; a: number }> = ({ t, a }) => {
  const d = k(t, a + 0.1, 0.8);
  return (
    <svg width={130} height={130} viewBox="0 0 120 120">
      <path d={`M10 30 H110 V48 C110 56 100 56 98 48 V${48 + 30 * d} C98 ${62 + 30 * d} 82 ${62 + 30 * d} 82 ${48 + 30 * d} V50 C82 56 70 56 70 48 V${48 + 14 * d} C70 ${58 + 14 * d} 56 ${58 + 14 * d} 56 ${48 + 14 * d} V50 C56 56 42 56 42 48 V${48 + 44 * d} C42 ${64 + 44 * d} 24 ${64 + 44 * d} 24 ${48 + 44 * d} V48 C24 56 10 56 10 48 Z`} fill={CREAM} />
    </svg>
  );
};
const IcoBacon: React.FC<{ t: number }> = ({ t }) => {
  const w = (o: number) => [...Array(7)].map((_, i) => `${i === 0 ? "M" : "L"}${10 + i * 17} ${50 + o + 14 * Math.sin(i * 1.4 + t * 6)}`).join(" ");
  return (
    <svg width={130} height={130} viewBox="0 0 120 120">
      <path d={w(-14)} stroke={CREAM} strokeWidth={16} strokeLinecap="round" strokeLinejoin="round" fill="none" />
      <path d={w(18)} stroke={CREAM} strokeWidth={16} strokeLinecap="round" strokeLinejoin="round" fill="none" opacity={0.7} />
    </svg>
  );
};
const Badge: React.FC<{ t: number; at: number; children: React.ReactNode }> = ({ t, at, children }) => {
  const e = pop(t, at, 0.5);
  return (
    <div style={{ position: "absolute", left: 540 - 105, top: 1160, width: 210, height: 210, borderRadius: 105, background: EMBER, boxShadow: "0 18px 40px rgba(0,0,0,0.5), 0 0 0 8px rgba(239,232,220,0.9)", display: "flex", alignItems: "center", justifyContent: "center", opacity: Math.min(1, e * 2), transform: `scale(${e.toFixed(3)}) rotate(${((1 - e) * -90).toFixed(1)}deg)` }}>
      {children}
    </div>
  );
};
const BEATS: [number, number, string, { z: [number, number]; x?: [number, number]; y?: [number, number]; o: string }, string, string, string, number, number][] = [
  [T_F, T_F2, "b0603", { z: [1.5, 1.3], x: [0, -40], o: "50% 45%" }, "50% 50%", "Carne", "no fogo", 9.6, 9.95],
  [T_F2, T_F3, "b0600", { z: [1.3, 1.52], y: [0, -40], o: "52% 60%" }, "50% 50%", "Queijo", "derretendo", 10.56, 10.92],
  [T_F3, T_G, "b0602", { z: [1.25, 1.45], x: [0, 30], o: "45% 45%" }, "40% 50%", "Bacon", "crocante", 11.66, 12.04],
];
const Itens: React.FC<{ t: number }> = ({ t }) => (
  <AbsoluteFill style={{ background: BLACK }}>
    {BEATS.map(([a, b, src, cam, pos], i) => {
      if (t < a - 0.1 || t > b + 0.25) return null;
      const e = i === 0 ? 1 : interpolate(t, [a - 0.1, a + 0.18], [0, 1], { ...cl, easing: OUT });
      const dir = i === 1 ? 1 : -1;
      return (
        <AbsoluteFill key={i} style={{ transform: `translateX(${((1 - e) * 1080 * dir).toFixed(1)}px)` }}>
          <Photo t={t} src={src} a={a - 0.1} b={b + 0.25} cam={cam} pos={pos} />
        </AbsoluteFill>
      );
    })}
    <Shade h={1100} />
    {BEATS.map(([a, b, , , , w1, w2, t1, t2], i) => (t >= a - 0.1 && t < b - 0.02 ? (
      <React.Fragment key={i}>
        <Badge t={t} at={a + 0.05}>{i === 0 ? <IcoFlame t={t} /> : i === 1 ? <IcoDrip t={t} a={a} /> : <IcoBacon t={t} />}</Badge>
        <Lettering t={t} items={[[w1, t1], [w2, t2, true]]} base={118} />
      </React.Fragment>
    ) : null))}
  </AbsoluteFill>
);

// ───────── 6 · o burger desenhado, montado camada por camada, e a mordida ─────────
const BITE = 16.0;
const Montagem: React.FC<{ t: number }> = ({ t }) => {
  const L = (at: number) => {
    const e = interpolate(t, [at - 0.12, at + 0.12], [0, 1], { ...cl, easing: Easing.in(Easing.quad) });
    const sq = t > at + 0.12 ? Math.max(0, 1 - (t - at - 0.12) / 0.25) * Math.sin(((t - at - 0.12) / 0.25) * Math.PI) : 0;
    return { y: (1 - e) * -1300, sq, on: t >= at - 0.12 };
  };
  const layers: [number, (sq: number) => React.ReactNode][] = [
    [13.44, () => <><path d="M170 1390 H910 V1420 C910 1480 860 1520 800 1520 H280 C220 1520 170 1480 170 1420 Z" fill={BUN} /><rect x={170} y={1390} width={740} height={22} fill={BUN_HI} /></>],
    [13.6, () => <><rect x={150} y={1290} width={780} height={100} rx={50} fill={MEAT} /><rect x={180} y={1298} width={720} height={26} rx={13} fill={MEAT_HI} />{[...Array(8)].map((_, i) => <circle key={i} cx={210 + i * 95} cy={1350 + (i % 2) * 12} r={7} fill="#2A120A" />)}</>],
    [14.0, () => {
      const d = k(t, 14.1, 0.9);
      return <path d={`M140 1262 H940 L930 1292 L860 ${1292 + 70 * d} L830 1292 L700 1292 L670 ${1292 + 40 * d} L640 1292 L420 1292 L390 ${1292 + 90 * d} L360 1292 L230 1292 L210 ${1292 + 50 * d} L190 1292 Z`} fill={CHEESE} strokeLinejoin="round" stroke={CHEESE} strokeWidth={14} />;
    }],
    [14.21, () => <path d={[...Array(14)].map((_, i) => `${i === 0 ? "M" : "L"}${180 + i * 55} ${1244 + 14 * Math.sin(i * 1.5)}`).join(" ")} stroke={BACON} strokeWidth={30} strokeLinecap="round" strokeLinejoin="round" fill="none" />],
    [14.54, () => <path d={`M140 1222 ${[...Array(17)].map((_, i) => `Q${160 + i * 48} ${i % 2 ? 1262 : 1196} ${184 + i * 48} 1226`).join(" ")} L940 1230 L930 1210 L150 1210 Z`} fill={LETTUCE} />],
    [14.66, () => <><rect x={210} y={1170} width={300} height={40} rx={20} fill={TOMATO} /><rect x={560} y={1170} width={310} height={40} rx={20} fill={TOMATO} /></>],
    [15.0, () => <><path d="M170 1172 C170 960 330 880 540 880 C750 880 910 960 910 1172 Z" fill={BUN} /><path d="M170 1172 H910 V1150 H170 Z" fill={BUN_LO} /><ellipse cx={420} cy={970} rx={130} ry={40} fill={BUN_HI} opacity={0.7} transform="rotate(-14 420 970)" /></>],
  ];
  const bite = k(t, BITE - 0.04, 0.16);
  const cam = 0.94 + 0.08 * lin(t, T_G, 15.5);
  const punch = interpolate(t, [15.5, 15.75], [0, 1], { ...cl, easing: OUT });
  return (
    <AbsoluteFill style={{ background: BLACK }}>
      <div style={{ position: "absolute", left: 90, right: 90, top: 820, height: 820, borderRadius: "50%", background: "radial-gradient(closest-side, rgba(210,88,42,0.3), rgba(210,88,42,0))" }} />
      <AbsoluteFill style={{ transform: `scale(${(cam + 0.1 * punch).toFixed(4)}) rotate(${(-2 + 2 * lin(t, T_G, T_H) - 2 * punch).toFixed(2)}deg)`, transformOrigin: "540px 1200px" }}>
        <svg width={1080} height={1920} style={{ position: "absolute", left: 0, top: 0 }}>
          <defs>
            <mask id="mrBite">
              <rect x={0} y={0} width={1080} height={1920} fill="white" />
              {bite > 0 ? [[860, 930, 120], [940, 1060, 120], [930, 1200, 110], [790, 870, 90]].map(([x, y, r], i) => <circle key={i} cx={x} cy={y} r={r * bite} fill="black" />) : null}
            </mask>
          </defs>
          <ellipse cx={540} cy={1540} rx={400} ry={26} fill="#000" opacity={0.6} />
          <g mask="url(#mrBite)">
            {layers.map(([at, draw], i) => {
              const l = L(at);
              if (!l.on) return null;
              return <g key={i} transform={`translate(0 ${l.y.toFixed(1)}) translate(540 1520) scale(${(1 + 0.05 * l.sq).toFixed(3)} ${(1 - 0.06 * l.sq).toFixed(3)}) translate(-540 -1520)`}>{draw(l.sq)}</g>;
            })}
          </g>
          {/* migalhas da mordida */}
          {t > BITE ? [...Array(9)].map((_, i) => {
            const a = t - BITE; const ang = -1.2 + rnd(i) * 1.6; const v = 500 + rnd(i + 4) * 500;
            return <circle key={i} cx={900 + Math.cos(ang) * v * a} cy={1000 + Math.sin(ang) * v * a + 900 * a * a} r={8 + rnd(i + 2) * 8} fill={i % 3 ? BUN : LETTUCE} opacity={Math.max(0, 1 - a / 0.6)} />;
          }) : null}
        </svg>
      </AbsoluteFill>
      <Lettering t={t} items={[["O verdadeiro sabor", 13.44], ["de churrasco", 14.66, true]]} bottom={1300} out={15.28} />
      {t >= 15.45 ? <Lettering t={t} items={[["em cada", 15.55], ["mordida", 16.0, true]]} bottom={1300} base={130} /> : null}
    </AbsoluteFill>
  );
};

// ───────── 7 · quando: folhas de calendário, relógio e a lua da noite ─────────
const DIAS: [string, number][] = [["SEX", 16.93], ["SÁB", 17.18], ["DOM", 17.42]];
const Quando: React.FC<{ t: number }> = ({ t }) => {
  const h = pop(t, 18.7, 0.5);
  const lbl = k(t, 18.15, 0.35);
  const moon = k(t, 18.95, 0.7);
  const cam = interpolate(t, [T_H, T_I + 0.3], [1.08, 0.98], { ...cl, easing: INOUT });
  return (
    <AbsoluteFill style={{ background: BLACK }}>
      <div style={{ position: "absolute", inset: 0, background: "linear-gradient(180deg, #17110F 0%, #0A0807 60%)", opacity: moon }} />
      <AbsoluteFill style={{ transform: `scale(${cam.toFixed(4)})` }}>
        {/* lua e estrelas no "da noite" */}
        <svg width={1080} height={1920} style={{ position: "absolute", left: 0, top: 0 }}>
          <defs><mask id="mrMoon"><rect width={1080} height={1920} fill="white" /><circle cx={590} cy={300 + (1 - moon) * 200} r={92} fill="black" /></mask></defs>
          <circle cx={540} cy={330 + (1 - moon) * 200} r={110} fill={CREAM} opacity={moon} mask="url(#mrMoon)" />
          {[[260, 260], [820, 220], [180, 470], [900, 470], [700, 140]].map(([x, y], i) => (
            <circle key={i} cx={x} cy={y} r={6 + 3 * Math.sin(t * 5 + i * 2)} fill={CREAM} opacity={k(t, 19.0 + i * 0.07, 0.3) * (0.6 + 0.4 * Math.sin(t * 6 + i))} />
          ))}
        </svg>
        <div style={{ position: "absolute", left: 0, right: 0, top: 620, display: "flex", justifyContent: "center", gap: 30, perspective: 900 }}>
          {DIAS.map(([d, at], i) => {
