export const cl = { extrapolateLeft: "clamp", extrapolateRight: "clamp" } as const;
export const OUT = Easing.out(Easing.cubic);
export const INOUT = Easing.inOut(Easing.sin);
export const k = (t: number, a: number, d: number) => interpolate(t, [a, a + d], [0, 1], { ...cl, easing: OUT });
export const lin = (t: number, a: number, b: number) => interpolate(t, [a, b], [0, 1], cl);
export const pop = (t: number, a: number, d: number) => interpolate(t, [a, a + d], [0, 1], { ...cl, easing: Easing.out(Easing.back(1.7)) });

