export const Photo: React.FC<{ t: number; src: string; a: number; b: number; cam: Cam; pos?: string; dark?: number }> = ({ t, src, a, b, cam, pos = "50% 50%", dark = 0 }) => {
  const p = interpolate(t, [a, b], [0, 1], { ...cl, easing: INOUT });
  const m = (v?: [number, number]) => (v ? v[0] + (v[1] - v[0]) * p : 0);
  return (
    <AbsoluteFill style={{ overflow: "hidden", background: BLACK }}>
      <Img src={staticFile(`marcio/${src}.jpg`)} style={{ width: "100%", height: "100%", objectFit: "cover", objectPosition: pos, transform: `translate(${m(cam.x).toFixed(1)}px, ${m(cam.y).toFixed(1)}px) scale(${m(cam.z).toFixed(4)}) rotate(${m(cam.r).toFixed(2)}deg)`, transformOrigin: cam.o ?? "50% 50%" }} />
      {dark > 0 ? <AbsoluteFill style={{ background: BLACK, opacity: dark }} /> : null}
    </AbsoluteFill>
  );
};

