// ───────── lettering embaixo: linhas creme e faixa laranja; entra e fica parado ─────────
export type Line = [string, number, boolean?];
const W = 840; // coluna central (margem de 120 px)
const fit = (s: string, base: number, wide: boolean) => Math.min(base, Math.floor((wide ? W - 70 : W) / (s.length * (wide ? 0.7 : 0.6))));
export const Lettering: React.FC<{ t: number; items: Line[]; bottom?: number; out?: number; base?: number }> = ({ t, items, bottom = 230, out, base = 104 }) => {
  const gone = out !== undefined ? k(t, out, 0.18) : 0;
  if (gone >= 1) return null;
  return (
    <div style={{ position: "absolute", left: 0, right: 0, bottom, display: "flex", flexDirection: "column", alignItems: "center", gap: 14, opacity: 1 - gone }}>
      {items.map(([s, at, hi], i) => {
        const e = pop(t, at - 0.06, 0.4);
        const f = k(t, at - 0.06, 0.22);
        if (hi) {
          const size = fit(s, base, true);
          const bar = k(t, at - 0.1, 0.28);
          return (
            <div key={i} style={{ position: "relative", padding: "14px 34px 18px", opacity: f }}>
              <div style={{ position: "absolute", inset: 0, background: EMBER, borderRadius: 10, transform: `scaleX(${bar.toFixed(3)})`, transformOrigin: "0% 50%", boxShadow: "0 18px 40px rgba(0,0,0,0.45)" }} />
              <div style={{ position: "relative", fontFamily: WIDE, fontSize: size, lineHeight: 1, color: CREAM, letterSpacing: 1, whiteSpace: "nowrap", transform: `translateY(${((1 - e) * 40).toFixed(1)}px) scale(${(0.85 + 0.15 * e).toFixed(3)})` }}>{s.toUpperCase()}</div>
            </div>
          );
        }
        const size = fit(s, base * 0.86, false);
        return (
          <div key={i} style={{ fontFamily: SANS, fontWeight: 800, fontSize: size, lineHeight: 1.08, color: CREAM, whiteSpace: "nowrap", textShadow: "0 6px 26px rgba(0,0,0,0.7)", opacity: f, transform: `translateY(${((1 - e) * 46).toFixed(1)}px) scale(${(0.88 + 0.12 * e).toFixed(3)})` }}>{s}</div>
        );
      })}
    </div>
  );
};

