      <div style={{ position: "absolute", left: 0, right: 0, top: 1500, textAlign: "center", fontFamily: SANS, fontWeight: 600, fontSize: 46, letterSpacing: 4, color: CREAM, opacity: info, transform: `translateY(${((1 - info) * 26).toFixed(1)}px)` }}>
        SEX A DOM <span style={{ color: EMBER_HI }}>•</span> A PARTIR DAS 19H
      </div>
    </AbsoluteFill>
  );
};

// ───────── transições: uma diferente em cada troca ─────────
export type Tr = "flash" | "zoom" | "cut" | "blur" | "wipe" | "ember";
export const Wrap: React.FC<{ t: number; at: number; tr: Tr; children: React.ReactNode }> = ({ t, at, tr, children }) => {
  if (tr === "cut") return <AbsoluteFill>{children}</AbsoluteFill>;
  const e = interpolate(t, [at - 0.18, at + 0.18], [0, 1], { ...cl, easing: INOUT });
  if (tr === "zoom") return <AbsoluteFill style={{ opacity: e, transform: `scale(${(1.25 - 0.25 * e).toFixed(4)})`, filter: e < 1 ? `blur(${((1 - e) * 18).toFixed(1)}px)` : undefined }}>{children}</AbsoluteFill>;
  if (tr === "blur") return <AbsoluteFill style={{ opacity: e, filter: e < 1 ? `blur(${((1 - e) * 24).toFixed(1)}px)` : undefined }}>{children}</AbsoluteFill>;
  if (tr === "wipe") return <AbsoluteFill style={{ clipPath: `inset(0 0 0 ${((1 - e) * 100).toFixed(2)}%)` }}>{children}</AbsoluteFill>;
  return <AbsoluteFill style={{ opacity: t >= at ? 1 : 0 }}>{children}</AbsoluteFill>;
};
export const Flash: React.FC<{ t: number; at: number; color: string }> = ({ t, at, color }) => {
  const o = interpolate(t, [at - 0.08, at, at + 0.3], [0, 0.85, 0], cl);
  return o > 0 ? <AbsoluteFill style={{ background: color, opacity: o, mixBlendMode: "screen" }} /> : null;
};

export const Marcio: React.FC = () => {
  const t = useCurrentFrame() / MR_FPS - LEAD;
  const scenes: [number, number, React.FC<{ t: number }>, Tr][] = [
    [-1, T_C, Gancho, "cut"], [T_C, T_D, Agora, "zoom"], [T_D, T_E, Marca, "flash"], [T_E, T_F, Brasa, "blur"],
    [T_F, T_G, Itens, "zoom"], [T_G, T_H, Sabor, "blur"], [T_H, T_I, Quando, "wipe"], [T_I, 99, Fecho, "flash"],
  ];
  return (
    <AbsoluteFill style={{ background: BLACK }}>
      {scenes.map(([a, b, S, tr], i) => {
        if (t < a - 0.3 || t > b + 0.3) return null;
        return <Wrap key={i} t={t} at={a} tr={tr}><S t={t} /></Wrap>;
      })}
      <Flash t={t} at={T_D} color={EMBER} />
      <Flash t={t} at={T_I} color={EMBER} />
      <Flash t={t} at={T_B} color="#FFFFFF" />
    </AbsoluteFill>
  );
};

